11	#[derive(Clone, Copy, Debug)]
12	pub struct Item {
13	    pub item_type: ItemType,
14	}
15	
16	impl Item {
17	    pub fn new(item_type: ItemType) -> Self {
18	        Self { item_type }
19	    }
20	}
21	
22	const PROCESSING_FEE: u64 = 5;
23	
24	/// Every component is insured at the same uniform rate, whatever its type.
25	const COMPONENT_BASE_PREMIUM: u64 = 25;
26	
27	fn base_premium(item_type: ItemType) -> u64 {
28	    match item_type {
29	        ItemType::Sword => 100,
30	        ItemType::Amulet => 60,
31	        ItemType::Staff => 80,
32	        ItemType::Potion => 40,
33	        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
34	    }
35	}
36	
37	fn policy_base_premium(items: &[Item]) -> u64 {
38	    items.iter().map(|item| base_premium(item.item_type)).sum()
39	}
40	
41	pub fn quote(items: &[Item]) -> u64 {
42	    policy_base_premium(items) + PROCESSING_FEE
43	}
